import re
s = open('/root/erp-exp-metadata.xml', encoding='utf-8').read()
def props(ent):
    m = re.search(r'<EntityType Name="%s".*?</EntityType>' % re.escape(ent), s, re.S)
    if not m: return None
    return re.findall(r'<(?:Property|NavigationProperty) Name="([^"]+)"(?:[^>]*Type="([^"]*)")?', m.group(0))
for ent in ('Document_Сделка',):
